#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m, p;
    if (!(cin >> n >> m >> p)) return 0;

    vector<int> row(n + 1);
    for (int i = 1; i <= n; ++i) {
        row[i] = i;
    }

    vector<int> col(m + 1);
    for (int j = 1; j <= m; ++j) {
        col[j] = j;
    }

    for (int k = 0; k < p; ++k) {
        char op;
        int a, b;
        cin >> op >> a >> b;
        if (op == 'L') {
            swap(row[a], row[b]);
        } else if (op == 'C') {
            swap(col[a], col[b]);
        }
    }

    for (int i = 1; i <= n; ++i) {
        long long base = (long long)(row[i] - 1) * m;
        for (int j = 1; j <= m; ++j) {
            long long ans = base + col[j];
            cout << ans << (j == m ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}
